import{_ as d,l as o,o as r,b as m,q as s,d as t,f as n,m as l}from"./chunks/framework.Tf23FRXt.js";const k=JSON.parse('{"title":"喜悦神域欧芙洛绪涅","description":"","frontmatter":{},"headers":[],"relativePath":"duty/911.htm.md","filePath":"duty/911.md","lastUpdated":1791098838000}'),A={name:"duty/911.htm.md"};function i(u,p,E,e,a,B){const S=o("Role"),O=o("Status");return r(),m("div",null,[p[14]||(p[14]=s('<h1 id="喜悦神域欧芙洛绪涅" tabindex="-1">喜悦神域欧芙洛绪涅</h1><p>整体难度不高，比较轻松的副本。</p><h1 id="boss-1-诺菲卡" tabindex="-1">BOSS 1 诺菲卡</h1><p>读条<mark>大地的恩惠</mark>，观察地面，花团锦簇为圆形 AOE，远离处理；绿草丛生为环形 AOE，靠近处理。</p><p>读条<mark>魅惑的叶花</mark>后，会给玩家附加若干秒的强制移动 debuff，倒计时结束后发生 2 秒的强制移动，该机制必然与上面大地的恩惠共同出现，不光需要注意场地和自己强制移动的方向，还要注意 debuff 的剩余时间。</p><p>场地出现黄 / 蓝圈和黄 / 蓝柱子后，柱子上会出现缩圈的特效，当缩圈到最小时，会产生对应颜色的 AOE，需要踩在相同颜色的圈里应对 AOE。</p><h1 id="boss-2-妮美雅和阿尔基克" tabindex="-1">BOSS 2 妮美雅和阿尔基克</h1>',7)),t("p",null,[p[0]||(p[0]=n("两个 BOSS 距离过近会产生连线，需要 2 个",-1)),l(S,{name:"tank"}),p[1]||(p[1]=n("T 将其拉开，有平血机制，随便打一个就行，一般推荐打",-1)),p[2]||(p[2]=t("strong",null,"妮美雅",-1)),p[3]||(p[3]=n("以便处理机制。",-1))]),p[15]||(p[15]=t("p",null,[n("妮美雅读条"),t("mark",null,"命运的纺车"),n("给玩家发卡，分为粉绿色的爱恋或红蓝色的冰火，在一场战斗中，只会出现爱恋或冰火其中之一。")],-1)),t("ul",null,[t("li",null,[p[4]||(p[4]=n("爱恋的命运：中",-1)),l(O,{id:3385,name:"爱恋的命运"}),p[5]||(p[5]=n("的人，倒计时结束时要背对妮美雅；中",-1)),l(O,{id:3386,name:"爱恋的命运：逆位"}),p[6]||(p[6]=n("的人，倒计时结束时要面对妮美雅（BOSS 身上有带问号的大眼睛标记）。",-1))]),t("li",null,[p[7]||(p[7]=n("冰火的命运：中",-1)),l(O,{id:3387,name:"热火的命运"}),p[8]||(p[8]=n("的人，倒计时结束时要原地不动；中",-1)),l(O,{id:3388,name:"热火的命运：逆位"}),p[9]||(p[9]=n("的人，倒计时结束时要保持移动（跳跃或左右移动均可）。",-1))])]),p[16]||(p[16]=t("p",null,"阿尔基克使用全屏 AOE 后，场地上会出现一些黑色的线形区域，此时观察妮美雅读条：",-1)),p[17]||(p[17]=t("ul",null,[t("li",null,"水之倾泻：不要踩黑色区域，散开处理（有散开提示）"),t("li",null,"重力操纵：站在黑色区域里，否则附赠伤害和易伤。")],-1)),p[18]||(p[18]=t("p",null,"场地中央出现带箭头的水波直线 AOE，先在 AOE 两侧躲避，第一次 AOE 炸开后立刻向中央移动（为直线扩散型 AOE）。",-1)),t("p",null,[p[10]||(p[10]=n("死刑",-1)),p[11]||(p[11]=t("mark",null,"群岩",-1)),p[12]||(p[12]=n("需要 2 个 T 分摊，请没有拉怪的",-1)),l(S,{name:"tank"}),p[13]||(p[13]=n("T 前去参与分摊。",-1))]),p[19]||(p[19]=s('<p>场地上出现 3 个柱子，并且柱子上方分别有 1、2、3 个菱形标记时，妮美雅会依次跳跃到柱子位置并使用击退。需要先在 1 的下方略微偏 2 的方向等待，被击飞后略微调整姿势准备击飞到 3 的方向，再次被击飞后再调整一次姿势防止被击飞到场外即可。</p><p>发卡和击飞柱子都有可能被阿尔基克时间操作连线，被连线的柱子会变为第一个击退的，一定要注意。</p><h1 id="boss-3-哈罗妮" tabindex="-1">BOSS 3 哈罗妮</h1><p>开场 AOE 后，BOSS 跳回中场读条<mark>寒枪四连</mark>，然后依次出现 4 个 AOE 预兆，推荐站在 4 个 AOE 交界的地方来回移动躲避。AOE 衔接速度较快，如果实在躲闪不急可以硬吃一个，吃多了可能来不及救。</p><p>场地上出现 3 个塔后，大体按照左上 A，右上 C，中间正南 B 的方向踩塔，如果你的位置赶不到自己小队的塔，就就近踩一个，务必要踩。</p><p>读条<mark>千枪连刺</mark>时，BOSS 周围出现一堆红圈，然后红圈逐渐向某一个位置移动，BOSS 会以红圈最后集合消失的地方为方向，放 180 度 AOE 攻击。</p><p>读条<mark>伏枪</mark>时，场地外出现 2 组金色的剑阵，剑阵会向其所指方向释放半场 AOE，只有 1/4 场地安全。</p><p>战女神之意 / 愤为环形步进式 AOE（一个从外向内，一个从内向外），不用看读条，看场地上的 AOE 提示即可，注意躲避。</p><p>场地上出现形状夸张的 AOE 和 3 个枪后，找自己队伍的方向打枪（注意站到安全区里），场地中央还有一把枪会放带旋转的直线 AOE，注意观察枪上的箭头方向，站到反方向躲避即可。</p><h1 id="boss-4-梅茵菲娜" tabindex="-1">BOSS 4 梅茵菲娜</h1><p>开场后不久，BOSS 在场边召唤一个月亮，当月亮变为满月时，释放巨～～宽的直线 AOE，而且非常疼，务必躲开（地板上有线可以作为参考）。</p><p>对 T 死刑为直线 AOE，注意位置。</p><p>之后出现满地 AOE，最后 3 个大圈 AOE BOSS 会飞过去砸，务必追着 BOSS 跑，第三下砸完之后会立刻接月环（需要靠近处理）。</p><p>之后场地上出现 4 个小月亮和圆形区域，月亮为 2 个新月（发黑）和 2 个上弦月（半黑半亮），4 个月亮都会逐渐变为满月，因此先在新月区域躲避，等上弦月炸了之后移动到安全区。</p><p>小怪阶段带有大量分散机制，注意处理。</p><p>之后 BOSS 会召唤狗狗达拉伽布，狗狗只会使用半场 AOE，但是会和 BOSS 本体机制形成复合机制，冷静处理即可（打的快就不会有特别复杂的复合机制，如果打得慢可能需要治疗留一下 LB）。</p>',16))])}const f=d(A,[["render",i]]);export{k as __pageData,f as default};
